async function reserveSeat(client, sessionId) {
  await client.query('BEGIN');
  const { rows } = await client.query('SELECT capacity, booked FROM sessions WHERE id = $1 FOR UPDATE', [sessionId]);
  if (rows[0].booked >= rows[0].capacity) { await client.query('ROLLBACK'); return false; }
  await client.query('UPDATE sessions SET booked = booked + 1 WHERE id = $1', [sessionId]);
  await client.query('COMMIT');
  return true;
}

module.exports = { reserveSeat };

