const crypto = require('node:crypto');
const cfg = require('./config');

function sign(body) {
  const payload = Object.keys(body).sort().map(k => `${k}=${body[k]}`).join('&');
  return crypto.createHmac('sha256', cfg.merchantKey).update(payload).digest('hex');
}

module.exports = { sign };

